function attachPanel(){const panel=$('advanced'),button=$('viewMenuButton');function layout(){document.documentElement.style.setProperty('--ui-header-bottom',(document.querySelector('header').getBoundingClientRect().bottom+8)+'px')}function sync(){button.setAttribute('aria-expanded',String(panel.open&&!panel.chipFloatingPanel?.collapsed));layout()}function setOpen(open){panel.open=open;if(open){panel.chipFloatingPanel?.setCollapsed(false);ChipUI.closeMenu()}sync()}button.addEventListener('click',()=>setOpen(!panel.open||panel.chipFloatingPanel?.collapsed));$('closeSettings').addEventListener('click',()=>setOpen(false));panel.addEventListener('toggle',sync);panel.addEventListener('panelstatechange',sync);window.addEventListener('resize',layout);setOpen(true);return {setPinned:on=>panel.chipFloatingPanel?.setPinned(on),setOpen}}

